css:
[data-bz-node="faq"] .bz-faqs { border-top: 1px solid var(--line); }
[data-bz-node="faq"] .bz-faqs { display: block; }
[data-bz-node="faq"] .bz-faq { background: none; border: 0; border-bottom: 1px solid var(--line); border-radius: 0; padding: 0; margin: 0; }
[data-bz-node="faq"] .bz-faq summary { list-style: none; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 20px 0; cursor: pointer; font: 700 22px/1.2 var(--font-heading); color: var(--hcm-navy); }
[data-bz-node="faq"] .bz-faq summary::-webkit-details-marker { display: none; }
[data-bz-node="faq"] .bz-faq summary::after { content: "+"; flex: none; width: 34px; height: 34px; display: flex; align-items: center; justify-content: center; background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius-input); font: 700 20px/1 var(--font-heading); color: var(--accent); }
[data-bz-node="faq"] .bz-faq[open] summary::after { content: "\2212"; }
[data-bz-node="faq"] .bz-faq summary:hover { color: var(--accent); }
[data-bz-node="faq"] .bz-faq__a { font-size: 17px; line-height: 1.65; color: var(--hcm-body); padding: 0 50px 22px 0; }
[data-bz-node="faq"] .bz-widget__h { display: none; }

js:
// One answer open at a time, and the first open on arrival, as the design has it.
// Without this script every question starts closed and each opens on its own.
document.querySelectorAll('[data-bz-section="faq-band"] .bz-faqs').forEach(function (list, n) {
  var items = list.querySelectorAll('details');
  items.forEach(function (item, i) {
    item.setAttribute('name', 'hcm-faq-' + n);
    if (i === 0) item.open = true;
    item.addEventListener('toggle', function () {
      if (!item.open) return;
      items.forEach(function (other) { if (other !== item) other.open = false; });
    });
  });
});
